"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { CopyHelper } from "theme/components/CopyHelper";
import { Flex, Image, Text, styled } from "ui/src";
import { colors } from "ui/src/theme";
import { shortenAddress } from "utilities/src/addresses";
const ProfileImage = styled(Image, {
  borderRadius: "$roundedFull",
  objectFit: "cover",
  variants: {
    size: {
      small: { width: 24, height: 24 },
      medium: { width: 32, height: 32 },
      large: { width: 40, height: 40 }
    }
  }
});
const FallbackAvatar = styled(Flex, {
  borderRadius: "$roundedFull",
  backgroundColor: "$neutral1",
  alignItems: "center",
  justifyContent: "center",
  variants: {
    size: {
      small: { width: 24, height: 24 },
      medium: { width: 32, height: 32 },
      large: { width: 40, height: 40 }
    }
  }
});
const ProfileText = styled(Text, {
  variants: {
    type: {
      name: {
        fontWeight: "$bold",
        color: "$neutral1"
      },
      address: {
        color: "$neutral2",
        fontSize: "$small"
      },
      tier: {
        color: "$accent1",
        fontSize: "$small",
        fontWeight: "$medium"
      }
    },
    size: {
      small: { variant: "body3" },
      medium: { variant: "body2" },
      large: { variant: "body1" }
    }
  }
});
export default function UserProfileDisplay({
  address,
  profile,
  size = "medium",
  showFullAddress = false,
  showCopyButton = true
}) {
  const displayAddress = showFullAddress ? address : shortenAddress(address);
  const displayName = profile?.name || shortenAddress(address);
  const hasProfileImage = profile?.profilePictureUrl && profile.profilePictureUrl !== "";
  const iconSize = size === "small" ? 16 : size === "medium" ? 20 : 24;
  return <Flex row alignItems="center" gap="$spacing12">
      {
    /* Profile Image or Fallback */
  }
      {hasProfileImage ? <img
    style={{ borderRadius: "50%", objectFit: "cover" }}
    height={24}
    width={24}
    src={profile.profilePictureUrl}
    alt={`${displayName} profile`}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  /> : <FallbackAvatar size={size}>
          <LogoProvider color={colors.black} size={iconSize} />
        </FallbackAvatar>}

      {
    /* Profile Info */
  }
      <Flex flexDirection="column" gap="$spacing4">
        <Flex row alignItems="center" gap="$spacing8">
          <ProfileText variant="body3" whiteSpace="nowrap" overflow="hidden" textOverflow="ellipsis" maxWidth={100}>
            {displayName}
          </ProfileText>
          {
    /* {profile?.tier && (
      <ProfileText type="tier" size={size}>
        {profile.tier}
      </ProfileText>
    )} */
  }
        </Flex>

        {showCopyButton ? <CopyHelper visibleIcon color="$neutral2" iconSize={12} iconPosition="right" toCopy={address}>
            <ProfileText variant="body3" color={"$neutral2"}>
              {displayAddress}
            </ProfileText>
          </CopyHelper> : <ProfileText variant="body3" color={"$neutral2"}>
            {displayAddress}
          </ProfileText>}
      </Flex>
    </Flex>;
}
export function CompactUserProfile({ address, profile }) {
  return <UserProfileDisplay
    address={address}
    profile={profile}
    size="small"
    showFullAddress={false}
    showCopyButton={true}
  />;
}
export function EnhancedUserProfile({ address, profile }) {
  return <Flex flexDirection="column" gap="$spacing8">
      <UserProfileDisplay
    address={address}
    profile={profile}
    size="medium"
    showFullAddress={false}
    showCopyButton={true}
  />
      {profile?.description && <Text variant="body3" color="$neutral2" numberOfLines={2}>
          {profile.description}
        </Text>}
    </Flex>;
}
