"use strict";
const API_BASE_URL = "https://veleaderboard-bb21ef0e241a.herokuapp.com";
class LeaderboardApiError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
    this.name = "LeaderboardApiError";
  }
}
async function fetchWithErrorHandling(url) {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new LeaderboardApiError(`HTTP ${response.status}: ${response.statusText}`, response.status);
    }
    const data = await response.json();
    if (!data.success) {
      throw new LeaderboardApiError(data.error || "Unknown API error");
    }
    return data;
  } catch (error) {
    if (error instanceof LeaderboardApiError) {
      throw error;
    }
    throw new LeaderboardApiError(`Network error: ${error instanceof Error ? error.message : "Unknown error"}`);
  }
}
export const leaderboardApi = {
  /**
   * Health check endpoint
   */
  async getHealth() {
    const response = await fetch(`${API_BASE_URL}/health`);
    return response.json();
  },
  /**
   * Get paginated leaderboard data
   */
  async getLeaderboard(limit = 100, offset = 0) {
    const url = `${API_BASE_URL}/leaderboard?limit=${Math.min(limit, 1e3)}&offset=${offset}`;
    return fetchWithErrorHandling(url);
  },
  /**
   * Get top N wallets by voting power
   */
  async getTopWallets(count) {
    const url = `${API_BASE_URL}/leaderboard/top/${Math.min(count, 1e3)}`;
    return fetchWithErrorHandling(url);
  },
  /**
   * Get specific wallet details including locks
   */
  async getWalletDetails(address) {
    const url = `${API_BASE_URL}/wallet/${address}`;
    return fetchWithErrorHandling(url);
  },
  /**
   * Get general statistics
   */
  async getStats() {
    const url = `${API_BASE_URL}/stats`;
    return fetchWithErrorHandling(url);
  }
};
