"use strict";
import AbsLogoProvider from "components/Logo/AbsLogoProvider";
import { Flex, Separator, Text, styled } from "ui/src";
import { useTopWallets } from "../hooks/useLeaderboardData";
import { useProfileEnhancement } from "../hooks/useProfileEnhancement";
import { formatABX, formatMultiplier, formatNumber } from "../utils/formatters";
import PrismaticBurst from "./PrismaticBurst";
import { EnhancedUserProfile } from "./UserProfileDisplay";
export default function TopPosition() {
  const { data: topWallets, loading, error } = useTopWallets(3);
  const { enhancedData: enhancedTopWallets, profilesLoading } = useProfileEnhancement(topWallets);
  console.log("topWallets", topWallets);
  console.log("enhancedTopWallets", enhancedTopWallets);
  const topPositions = enhancedTopWallets.slice(0, 3).map((wallet, index) => {
    const configs = [
      {
        id: "gold",
        borderColor: "$absGreen",
        backgroundColor: "rgba(3, 210, 110, 0.1)",
        buttonColor: "$absGreen",
        buttonTextColor: "#FFFFFF",
        hasAnimation: true
      },
      {
        id: "silver",
        borderColor: "rgba(228, 228, 231,1)",
        backgroundColor: "rgba(228, 228, 231,0.1)",
        buttonColor: "rgba(228, 228, 231,1)",
        buttonTextColor: "rgba(3, 210, 110, 1)"
      },
      {
        id: "bronze",
        borderColor: "rgba(247, 148, 41, 1)",
        backgroundColor: "rgba(247, 148, 41, 0.1)",
        buttonColor: "rgba(247, 148, 41, 1)",
        buttonTextColor: "#ffffffff"
      }
    ];
    const config = configs[index] || configs[2];
    return {
      ...config,
      rank: wallet.rank,
      username: `Holder #${wallet.rank}`,
      address: wallet.address,
      profile: wallet.profile,
      stats: [
        { title: "Voting Power", value: formatNumber(wallet.votingPower) },
        { title: "Locked", value: formatABX(wallet.lockedABX) },
        { title: "Multiplier", value: formatMultiplier(wallet.multiplier) }
      ]
    };
  });
  if (loading || profilesLoading) {
    return <Flex>
        <Text variant="heading2" textAlign="center">
          Leaderboard
        </Text>
        <Flex centered py="$spacing40">
          <Text color="$neutral2" variant="body2">
            Loading top positions...
          </Text>
        </Flex>
      </Flex>;
  }
  if (error) {
    return <Flex>
        <Text variant="heading2" textAlign="center">
          Leaderboard
        </Text>
        <Flex centered py="$spacing40">
          <Text color="$statusCritical" variant="body2">
            {error}
          </Text>
        </Flex>
      </Flex>;
  }
  const Item = styled(Flex, {
    backdropFilter: "blur(5px)",
    borderRadius: "$rounded16",
    py: "$spacing12",
    px: "$spacing8",
    gap: "$spacing8",
    height: "100%",
    width: "100%",
    alignItems: "center",
    justifyContent: "center",
    flexDirection: "column",
    // backgroundColor: 'rgba(3, 210, 110, 0.1)',
    borderWidth: 1,
    borderColor: "rgba(3, 210, 110, 0.1)",
    transition: "all 0.2s ease",
    hoverStyle: {
      borderColor: "rgba(3, 210, 110, 1)"
    },
    style: {
      background: "radial-gradient(circle, rgba(3, 210, 110, 0.4), transparent 90%"
    }
  });
  const SilverItem = styled(Item, {
    backgroundColor: "rgba(228, 228, 231, 0.1)",
    borderColor: "rgba(228, 228, 231, 0.1)",
    hoverStyle: {
      borderColor: "rgba(228, 228, 231, 1)"
    },
    style: {
      background: "radial-gradient(circle, rgba(228, 228, 231, 0.4), transparent 90%"
    }
  });
  const BronzeItem = styled(Item, {
    backgroundColor: "rgba(247, 148, 41, 0.1)",
    borderColor: "rgba(247, 148, 41, 0.1)",
    hoverStyle: {
      borderColor: "rgba(247, 148, 41, 1)"
    },
    style: {
      background: "radial-gradient(circle, rgba(247, 148, 41, 0.4), transparent 90%"
    }
  });
  const ItemTitle = styled(Text, {
    color: "$neutral2",
    variant: "body3"
  });
  const ItemValue = styled(Text, {
    color: "$neutral1",
    variant: "body3",
    fontWeight: "$semibold"
  });
  const SeparatorItem = styled(Separator, {
    width: "100%",
    backgroundColor: "rgba(210, 189, 3, 0.0001)"
  });
  const renderPositionCard = (position) => {
    const StyledItem = position.id === "silver" ? SilverItem : position.id === "bronze" ? BronzeItem : Item;
    const boxShadownColor = position.id === "bronze" ? "rgba(247, 148, 41, 0.4)" : position.id === "gold" ? "rgba(3, 210, 110, 0.7)" : "rgba(228, 228, 231, 0.4)";
    const cardContent = <>
        {position.hasAnimation && <Flex opacity={0.25} position="absolute" inset={0} height={"100%"} width={"100%"}>
            <PrismaticBurst
      animationType="rotate3d"
      intensity={1}
      speed={0.25}
      distort={0}
      paused={false}
      offset={{ x: 0, y: 0 }}
      rayCount={20}
      mixBlendMode="none"
      colors={["#741dffff", "#4400ffff", "#741dffff"]}
    />
          </Flex>}

        <Flex row alignItems="flex-start" justifyContent="space-between" gap={"$gap12"} className="top">
          <EnhancedUserProfile address={position.address} profile={position.profile} />

          <a href="#" style={{ display: "none" }}>
            <Flex
      height={28}
      width={28}
      borderRadius={"$rounded4"}
      centered
      backgroundColor={position.buttonColor}
      transition="all 0.2s ease-in-out"
      hoverStyle={{ transform: "scale(0.97)", opacity: 0.9 }}
    >
              <AbsLogoProvider size={20} color={position.buttonTextColor} />
            </Flex>
          </a>
        </Flex>

        <Flex className="bottom" gap={"$spacing8"} $platform-web={{ display: "grid", gridTemplateColumns: "1fr" }}>
          {position.stats.splice(1, 1).map((stat, statIndex) => <StyledItem
      key={statIndex}
      className={stat.title === "Multiplier" ? "Multiplier" : void 0}
    >
              <ItemTitle>{stat.title}</ItemTitle>
              <SeparatorItem />
              <ItemValue>{stat.value}</ItemValue>
            </StyledItem>)}
        </Flex>
      </>;
    return <Flex
      key={position.id}
      mt={position.id !== "gold" ? 10 : 0}
      $md={{ mt: 0 }}
      p={"$spacing12"}
      borderWidth={2}
      borderColor={position.borderColor}
      borderRadius={"$rounded16"}
      gap={"$spacing24"}
      flexDirection="column"
      transition="all 0.2s ease-in-out"
      style={{
        background: `radial-gradient(circle, ${position.backgroundColor}, transparent 100%)`,
        boxShadow: position.id === "gold" ? "0px 0px 10px 5px rgba(3, 210, 110, 0.3)" : ""
      }}
      hoverStyle={{ boxShadow: `0px 0px 20px 0px ${boxShadownColor}` }}
    >
        {cardContent}
      </Flex>;
  };
  return <Flex>
      <Text variant="heading2" textAlign="center">
        Season 1
      </Text>
      <Flex
    gap={"$gap24"}
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr" }}
    $lg={{
      gridTemplateColumns: "1fr 1fr"
    }}
    $md={{
      gridTemplateColumns: "1fr"
    }}
    row
    mt={"$spacing28"}
  >
        {
    /* Rearrange to show: 2nd, 1st, 3rd (1st in middle) */
  }
        {topPositions[1] && renderPositionCard(topPositions[1])}
        {topPositions[0] && renderPositionCard(topPositions[0])}
        {topPositions[2] && renderPositionCard(topPositions[2])}
      </Flex>
    </Flex>;
}
