"use strict";
import { useCallback, useEffect, useState } from "react";
import { leaderboardApi } from "../api/leaderboardApi";
function transformWalletToTableValue(wallet) {
  const avgDaysRemaining = wallet.avg_days_remaining || 0;
  const multiplier = Math.min(1 + avgDaysRemaining / 365 * 0.5, 5);
  return {
    rank: wallet.rank,
    address: wallet.wallet_address,
    votingPower: wallet.voting_power,
    lockedABX: wallet.total_amount_locked_abx,
    activeLocks: wallet.active_locks,
    totalScore: wallet.voting_power,
    // Using voting power as total score
    multiplier
  };
}
export function useLeaderboardData(initialLimit = 50) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [total, setTotal] = useState(0);
  const fetchData = useCallback(
    async (reset = false) => {
      try {
        setLoading(true);
        setError(null);
        const currentOffset = reset ? 0 : offset;
        const response = await leaderboardApi.getLeaderboard(initialLimit, currentOffset);
        if (response.success && response.data) {
          const transformedData = response.data.map(transformWalletToTableValue);
          if (reset) {
            setData(transformedData);
            setOffset(initialLimit);
          } else {
            setData((prev) => [...prev, ...transformedData]);
            setOffset((prev) => prev + initialLimit);
          }
          setTotal(response.pagination?.total || 0);
          setHasMore((response.pagination?.returned || 0) === initialLimit);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to fetch leaderboard data");
      } finally {
        setLoading(false);
      }
    },
    [initialLimit, offset]
  );
  const refetch = useCallback(() => {
    setOffset(0);
    return fetchData(true);
  }, [fetchData]);
  const loadMore = useCallback(() => {
    if (!loading && hasMore) {
      return fetchData(false);
    }
    return Promise.resolve();
  }, [fetchData, loading, hasMore]);
  useEffect(() => {
    fetchData(true);
  }, []);
  return {
    data,
    loading,
    error,
    refetch,
    loadMore,
    hasMore,
    total
  };
}
export function useTopWallets(count = 10) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const fetchTop = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await leaderboardApi.getTopWallets(count);
      if (response.success && response.data) {
        const transformedData = response.data.map(transformWalletToTableValue);
        setData(transformedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch top wallets");
    } finally {
      setLoading(false);
    }
  }, [count]);
  useEffect(() => {
    fetchTop();
    const interval = setInterval(fetchTop, 5 * 60 * 1e3);
    return () => clearInterval(interval);
  }, [fetchTop]);
  return { data, loading, error, refetch: fetchTop };
}
export function useLeaderboardStats() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const fetchStats = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await leaderboardApi.getStats();
      if (response.success && response.stats) {
        setStats(response.stats);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch statistics");
    } finally {
      setLoading(false);
    }
  }, []);
  useEffect(() => {
    fetchStats();
    const interval = setInterval(fetchStats, 10 * 60 * 1e3);
    return () => clearInterval(interval);
  }, [fetchStats]);
  return { stats, loading, error, refetch: fetchStats };
}
